const form = $('Formulário de Escala').first().json;
const dbResult = $input.first().json;

// Usa celular do banco se encontrado, senão usa o digitado no formulário
let celularWA = dbResult.celular_whatsapp || '';
let membroCodigo = dbResult.codigo || null;
let membroNome = dbResult.nome || form['Nome do Membro'];

if (!celularWA && form['Celular (se não encontrar no sistema)']) {
  const digits = form['Celular (se não encontrar no sistema)'].replace(/\D/g, '');
  celularWA = digits.startsWith('55') ? digits : '55' + digits;
}

if (!celularWA) {
  throw new Error(`Celular não encontrado para: ${form['Nome do Membro']}. Informe o celular manualmente.`);
}

// Formata a data
const dataRaw = form['Data'] || '';
const dataFormatada = dataRaw.substring(0, 10); // YYYY-MM-DD

return [{ json: {
  membro_codigo:    membroCodigo,
  membro_nome:      membroNome,
  celular_whatsapp: celularWA,
  funcao:           form['Função'],
  evento:           form['Evento'],
  data_evento:      dataFormatada,
  hora_evento:      form['Hora'],
  criado_por:       form['Registrado por'] || 'Formulário'
}}];
